/// eye: the first sixteen hex digits of the SPKI hash in groups of
/// four, as the host's pairing dialog prints them.
public enum KeyFingerprint {
    public static func short(_ hex: String) -> String {
        let digits = Array(hex.prefix(16))
        return stride(from: 0, to: digits.count, by: 4)
            .map { String(digits[$0..<min($0 + 4, digits.count)]) }
            .joined(separator: " ")
    }
}

/// What the host's QR code holds while its pairing window is open: the
/// installation, the key to pin before the code is sent, the code, and
/// where the host answered from. Also pasted by hand.
public struct PairingInvite: Decodable, Sendable, Equatable {
    public let serverID: ServerID
    public let spkiSha256: String
    public let code: String
    public let addresses: [String]

    enum CodingKeys: String, CodingKey {
        case serverID = "server_id"
        case spkiSha256 = "spki_sha256"
        case code, addresses
    }

    public init(serverID: ServerID, spkiSha256: String, code: String, addresses: [String]) {
        self.serverID = serverID
        self.spkiSha256 = spkiSha256
        self.code = code
        self.addresses = addresses
    }

    /// The invite from the scanned or pasted text.
    public static func parse(_ text: String) throws -> PairingInvite {
        try Wire.decode(PairingInvite.self, from: Data(text.utf8))
    }
}

func run() async -> Int32 {
    let args = Array(CommandLine.arguments.dropFirst())
    guard let command = args.first else {
        print(usage)
        return 2
    }
    do {
        try await manager.load()
        switch command {
        case "discover":
            await discover(seconds: Double(args.dropFirst().first ?? "") ?? 3)
        case "pair":
            let rest = Array(args.dropFirst())
            let invite: PairingInvite
            if rest.count == 1 {
                invite = try PairingInvite.parse(rest[0])
            } else if rest.count == 3 {
                // The id is learned from the pairing reply; a placeholder
                // until then is refused, so read /info unpinned first.
                guard let address = Address(rest[0]) else { throw RemoteError.transport("bad address") }
                let probe = HostClient(address: address, pin: .expect(spkiSha256: rest[2]))
                let info = try await probe.info()
                invite = PairingInvite(
                    serverID: info.body.serverID, spkiSha256: rest[2], code: rest[1],
                    addresses: [rest[0]])
            } else {
                print(usage)
                return 2
            }
            try await manager.pair(invite: invite)
            await manager.rebuild()
            printStore(await manager.store)
        case "hosts":
            await manager.connectAll()
            printStore(await manager.store)
        case "forget":
            guard let id = args.dropFirst().first else {
                print(usage)
                return 2
            }
